  "event_title" text not null,
  "event_description" text,
  "visible_to_gp" boolean default true not null,
  "created_by" text,
  "created_at" timestamp with time zone default now() not null
);

create table public."visa_updates" (
  "id" uuid default gen_random_uuid() not null,
  "visa_case_id" uuid not null,
  "body" text not null,
  "visibility" text default 'gp'::text not null,
  "created_by" text,
  "created_at" timestamp with time zone default now() not null
);

create table public."webhook_events" (
  "id" uuid default gen_random_uuid() not null,
  "provider" text not null,
  "event_id" text not null,
  "event_type" text,
  "processed_at" timestamp with time zone default now() not null,
  "payload" jsonb
);

create table public."zoho_archive" (
  "id" uuid default gen_random_uuid() not null,
  "entity_type" text not null,
  "zoho_id" text not null,
  "payload" jsonb not null,
  "pulled_at" timestamp with time zone default now() not null,
  "created_at" timestamp with time zone default now() not null
);

create table public."zoho_sign_envelopes" (
  "envelope_id" text not null,
  "task_id" uuid,
  "user_id" uuid,
  "case_id" uuid,
  "template_id" text not null,
  "status" text not null,
  "recipient_contact" jsonb,
  "recipient_candidate" jsonb,
  "sent_at" timestamp with time zone,
  "completed_at" timestamp with time zone,
  "decline_reason" text,
  "previous_envelope_id" text,
  "correction_sections" text[],
  "correction_note" text,
  "signed_pdf_drive_id" text,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null
);


