-- @@section constraints_fk
-- Foreign keys (including those pointing at auth.users).
alter table public."ad_drafts" add constraint "ad_drafts_review_id_fkey" FOREIGN KEY (review_id) REFERENCES public.ad_reviews(id) ON DELETE SET NULL;
alter table public."ahpra_case_documents" add constraint "ahpra_case_documents_case_id_fkey" FOREIGN KEY (case_id) REFERENCES public.ahpra_cases(id) ON DELETE CASCADE;
alter table public."ahpra_cases" add constraint "ahpra_cases_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public."ahpra_events" add constraint "ahpra_events_actor_user_id_fkey" FOREIGN KEY (actor_user_id) REFERENCES auth.users(id);
alter table public."ahpra_events" add constraint "ahpra_events_case_id_fkey" FOREIGN KEY (case_id) REFERENCES public.ahpra_cases(id) ON DELETE CASCADE;
alter table public."ahpra_events" add constraint "ahpra_events_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public."ahpra_notifications" add constraint "ahpra_notifications_case_id_fkey" FOREIGN KEY (case_id) REFERENCES public.ahpra_cases(id) ON DELETE CASCADE;
alter table public."ahpra_notifications" add constraint "ahpra_notifications_recipient_user_id_fkey" FOREIGN KEY (recipient_user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
