-- @@section functions_late
-- Functions that take or return a table row type.

-- @@section views
-- Views and materialised views.
create view public."ahpra_case_readiness" with (security_invoker=on) as
SELECT c.id AS case_id,
    c.user_id,
    count(*) FILTER (WHERE d.source_type = 'gp'::text) AS gp_total,
    count(*) FILTER (WHERE d.source_type = 'gp'::text AND d.status = 'ready'::text) AS gp_ready,
    count(*) FILTER (WHERE d.source_type = 'gplink'::text) AS gplink_total,
    count(*) FILTER (WHERE d.source_type = 'gplink'::text AND d.status = 'ready'::text) AS gplink_ready,
    count(*) FILTER (WHERE d.status = 'rejected'::text) AS rejected_count,
    count(*) FILTER (WHERE d.status = ANY (ARRAY['not_ready'::text, 'pending'::text, 'rejected'::text])) AS missing_count
   FROM public.ahpra_cases c
     LEFT JOIN public.ahpra_case_documents d ON d.case_id = c.id
  GROUP BY c.id, c.user_id;

create view public."va_open_tickets_fifo" with (security_invoker=on) as
SELECT t.id,
    t.user_id,
    t.case_id,
    t.source_ticket_id,
    t.case_code,
    t.title,
    t.category,
    t.stage,
    t.substage,
    t.priority,
    t.status,
    t.created_at,
    t.updated_at,
    p.first_name,
    p.last_name,
    p.email AS gp_email,
    p.phone_number AS gp_phone
   FROM public.support_tickets t
     LEFT JOIN public.user_profiles p ON p.user_id = t.user_id
  WHERE t.status <> 'closed'::text
  ORDER BY t.created_at;


